{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Trametinib, the highest-transfer analogue, has a measured absolute oral bioavailability of 72.3% in patients with solid tumours using an oral tablet versus i.v. microtracer, directly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Regorafenib, a close analogue, shows 83% absolute oral bioavailability as a solution and 69% as a tablet, both clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Apalutamide, another high-transfer analogue, has approximately 100% absolute oral bioavailability in patients, indicating essentially complete oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Safinamide, a high-transfer analogue, has about 95% absolute oral bioavailability in patients under fasting conditions, strongly supporting high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Rimegepant, a structurally related oral drug, has 64% absolute bioavailability in healthy volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues with high assay-transfer scores show absolute oral bioavailability values well above 20%, mostly 45-100%. No analogue provides affirmative evidence for low bioavailability. The query is therefore predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement is available for the query molecule itself.",
    "Formulation-specific effects on the query are not directly tested.",
    "Potential first-pass metabolism or transporter effects specific to the query are inferred only from analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

